"""gen_column_docs - writes DATA_MODEL_COLUMNS.md from data_model.json (generated file, never edit by hand). Run: python3 -I gen_column_docs.py"""
import os
import sys

sys.path.insert(0, os.path.dirname(os.path.abspath(__file__)))
from lbmodel import SHARED, load_model  # noqa: E402

M = load_model()
out = ['# DATA_MODEL_COLUMNS - generated from data_model.json', '',
       'Generated by `fixtures/tools/gen_column_docs.py`. Do not edit by hand; edit `data_model.json` (a SHARED_CHANGELOG entry) and regenerate.', '',
       'Type key: text, int, bool (stored 0/1), date (ISO text), json, decimal(scale 4, stored integer x10^4). "Source" is the Tally XML tag, or the derivation for connector-computed columns. "V" is the verification state: L = legacy_seen, A = assumed (verify on a real Tally), D = derived.', '']
V = {'legacy_seen': 'L', 'assumed': 'A', 'derived': 'D'}
for t in M['tables_order']:
    x = M['tables'][t]
    out += ['## ' + t, '', 'Group: %s. Primary key: %s. Scope: %s.' % (x['group'], ', '.join(x['primary_key']), x['scope'])]
    if x.get('parent'):
        out.append('Parent: %s.' % x['parent']['table'])
    out.append('Indexes: ' + '; '.join('%s(%s)' % (i['name'], ', '.join(i['columns'])) for i in x['indexes']) + '.')
    out += ['', '| Column | Type | Default | Source | V | Note |', '|---|---|---|---|---|---|']
    for c in x['columns']:
        ty = c['type'] + ('(%s)' % c['kind'] if c.get('kind') else '')
        src = c.get('tally') or c.get('derive') or ''
        note = c.get('note', '')
        out.append('| %s | %s | %s | %s | %s | %s |' % (c['name'], ty, ('`%s`' % c['default']) if c.get('default') not in (None, '') else '', str(src).replace('|', '/'), V.get(c.get('verify'), ''), str(note).replace('|', '/')))
    out.append('')
with open(os.path.join(SHARED, 'DATA_MODEL_COLUMNS.md'), 'w', encoding='utf-8') as f:
    f.write('\n'.join(out) + '\n')
print('ok', len(out), 'lines')
